// import 'jasmine'; (google3-only)
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-pull-to-refresh.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** The live region of `politeness` in the shadow root of `el`. */
function annRegion(el: HTMLElement, politeness: 'polite' | 'assertive') {
  return el.shadowRoot!.querySelector<HTMLElement>(`[data-announcer="${politeness}"]`);
}

/** Waits (at most a second) until the live region holds `expected`, and returns its text. */
async function annText(el: HTMLElement, politeness: 'polite' | 'assertive', expected: string) {
  const text = () => annRegion(el, politeness)?.textContent?.trim() ?? '';
  // Checks once per frame (the shared until() helper, inlined).
  const end = performance.now() + 1000;
  while (text() !== expected && performance.now() < end) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
  }
  return text();
}

describe('<md-gb-pull-to-refresh> announcer contract (AnnouncerController)', () => {
  afterEach(() => container?.remove());

  it('announces "Refreshing" politely when a refresh starts, and clears it when it ends', async () => {
    // spec: loading-indicator-4621ff, progress-indicators-511521
    const root = await mount(html`
      <button id="before">Before</button>
      <md-gb-pull-to-refresh style="block-size: 300px"><div style="block-size: 600px">Content</div></md-gb-pull-to-refresh>
    `);
    const el = root.querySelector<any>('md-gb-pull-to-refresh')!;
    const before = root.querySelector<HTMLElement>('#before')!;
    before.focus();
    await settle();
    el.refresh();
    const expected = 'Refreshing';
    expect(expected).not.toBe('');
    expect(await annText(el, 'polite', expected)).toBe(expected);
    const region = annRegion(el, 'polite')!;
    expect(region.getAttribute('role')).toBe('status');
    expect(region.getAttribute('aria-live')).toBe('polite');
    expect(region.getAttribute('aria-atomic')).toBe('true');
    expect(document.activeElement).toBe(before);
    el.refreshing = false;
    await settle();
    expect(await annText(el, 'polite', '')).toBe('');
  });

  it('removes its live regions when it disconnects', async () => {
    const root = await mount(html`<md-gb-pull-to-refresh style="block-size: 300px"><div style="block-size: 600px">Content</div></md-gb-pull-to-refresh>`);
    const el = root.querySelector<any>('md-gb-pull-to-refresh')!;
    el.refresh();
    await annText(el, 'polite', 'Refreshing');
    expect(el.shadowRoot.querySelector('[data-announcer]')).not.toBeNull();
    el.remove();
    await settle();
    expect(el.shadowRoot.querySelector('[data-announcer]')).toBeNull();
  });
});
